-- 全部 200 条现有帖子。
--
-- 【点赞数】前端 Post.likes 是"给人看的文字"（'1.5万' / '6810' 混用），不能排序、不能加减。
-- 因此拆成三列：
--   likes        原始展示字符串（保留，前端有 5-6 处直接渲染它）
--   likes_count  规范数字，唯一真值来源（排序 / 加减 / 统计 / 后端用）
--   likes_display 展示字符串副本（冗余，便于对照；= likes）
-- 转换规则（与前端 src/pages/feed/lightboxData.ts 的 parseCount 完全等价）：
--   含"万": ROUND(REPLACE(likes,'万','')::numeric * 10000)::bigint
--   纯数字: REPLACE(REPLACE(likes,',',''),' ','')::bigint
-- 注意 '1.5万' 是有损格式（15000 与 15499 都显示为 '1.5万'），所以原始文案必须保留。
-- 详见 docs/数据对应表.md 第 4 节。

CREATE TABLE IF NOT EXISTS "posts" (
  "id" BIGINT PRIMARY KEY,
  "type" TEXT NOT NULL,
  "img" TEXT,
  "imgOverlay" TEXT,
  "quote" TEXT,
  "quoteEmoji" TEXT,
  "title" TEXT,
  "tags" JSONB,
  "author" TEXT NOT NULL,
  "likes" TEXT NOT NULL,
  "likes_count" BIGINT,
  "likes_display" TEXT,
  "duration" TEXT,
  "content" TEXT,
  "videoUrl" TEXT,
  "authorUserId" TEXT REFERENCES "users"("id"),
  "_seedOrigin" TEXT,
  -- 自检：likes_count 必须与 likes 文案一致，写错会被数据库直接拒绝
  CONSTRAINT "posts_likes_count_matches_display" CHECK ("likes_count" IS NULL OR "likes_count" =
    CASE WHEN "likes" LIKE '%万%'
      THEN ROUND(REPLACE("likes",'万','')::numeric * 10000)::bigint
      ELSE REPLACE(REPLACE("likes",',',''),' ','')::bigint END)
);

CREATE INDEX IF NOT EXISTS "idx_posts_authorUserId" ON "posts" ("authorUserId");

