  "authorUserId" TEXT REFERENCES "users"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_comments_postId" ON "comments" ("postId");

CREATE INDEX IF NOT EXISTS "idx_comments_authorUserId" ON "comments" ("authorUserId");

